@startuml

class RepairShop {
  + Name : string
  + Address : string
  + NumberOfEmployees : int
  + CalculateAverageSeniority() : float
  + CalculateLongestRepair() : int
}

class Employee {
  + TaxCode : string
  + Address : string
  + PhoneNumber : string
  + YearsOfService : int
}

class Director extends Employee {
  + Age : int
}

class Vehicle {
  + Model : string
  + Type : string
  + LicensePlate : string
  + YearOfRegistration : int
}

class Owner {
  + TaxCode : string
  + Address : string
  + PhoneNumber : string
}

class Repair {
  + Code : string
  + CheckInTime : datetime
  + CheckInDate : date
  + ReturnTime : time
  + ReturnDate : date
}

class Manager {
  + PerformStaffAnalysis(RepairShop) : void
  + PerformRepairAnalysis(RepairShop) : void
}

class AccountingOffice {
  + ReceiveManagementResults() : void
}

RepairShop "1" *-- "1..*" Employee : employs
RepairShop "1" -- "1" Director : managed by
RepairShop "1" -- "0..*" Repair : performs
Vehicle "1" -- "0..*" Repair : undergoes
Vehicle "0..*" -- "1" Owner : owned by
Owner "1" -- "0..*" Vehicle : owns
Manager ..> RepairShop : analyzes
Director ..> AccountingOffice : communicates results to

@enduml

